	}
}

// atomicWantV2Materials 是修正提交成功后 R1/v2 唯一允许的物料视图：
// 完整四项、顺序不变、最后一项不漏；数量以本次合法提交为准，不混入失败
// 提交里的旧用量（M2=2、M3=7），1.000 显示为 1、0.001 保留三位小数。
func atomicWantV2Materials() []MaterialView {
